class Array {
    int* data;
    int len;
public:
    Array(int n, int val) : data(new int[n]), len(n) {
        for (int i = 0; i < n; ++i) data[i] = val;
    }
    Array(const Array& o) : data(new int[o.len]), len(o.len) {
        for (int i = 0; i < len; ++i) data[i] = o.data[i];
        std::cout << "Copy ";
    }
    friend void swap(Array& a, Array& b) noexcept {
        std::swap(a.data, b.data);
        std::swap(a.len, b.len);
        std::cout << "Swap ";
    }
    Array& operator=(Array other) noexcept {
        swap(*this, other);
        return *this;
    }
    ~Array() { delete[] data; }
    int first() const { return data[0]; }
};

int main() {
    Array a(2, 10), b(2, 99);
    a = b;
    std::cout << a.first() << "\n";
}

